1. import { concat, last, nth, isEmpty } from 'lodash';
2. import visitParents from 'unist-util-visit-parents';
3. 
4. /**
5.  * remarkUnwrapInvalidNest
6.  *
7.  * Some MDAST node types can only be nested within specific node types - for
8.  * example, a paragraph can't be nested within another paragraph, and a heading
9.  * can't be nested in a "strong" type node. This kind of invalid MDAST can be
10.  * generated by rehype-remark from invalid HTML.
11.  *
12.  * This plugin finds instances of invalid nesting, and unwraps the invalidly
13.  * nested nodes as far up the parental line as necessary, splitting parent nodes
14.  * along the way. The resulting node has no invalidly nested nodes, and all
15.  * validly nested nodes retain their ancestry. Nodes that are emptied as a
16.  * result of unnesting nodes are removed from the tree.
17.  */
18. export default function remarkUnwrapInvalidNest() {
19.   return transform;
20. 
21.   function transform(tree) {
22.     const invalidNest = findInvalidNest(tree);
23. 
24.     if (!invalidNest) return tree;
25. 
26.     splitTreeAtNest(tree, invalidNest);
27. 
28.     return transform(tree);
29.   }
30. 
31.   /**
32.    * visitParents uses unist-util-visit-parent to check every node in the
33.    * tree while having access to every ancestor of the node. This is ideal
34.    * for determining whether a block node has an ancestor that should not
35.    * contain a block node. Note that it operates in a mutable fashion.
36.    */
37.   function findInvalidNest(tree) {
38.     /**
39.      * Node types that are considered "blocks".
40.      */
41.     const blocks = ['paragraph', 'heading', 'code', 'blockquote', 'list', 'table', 'thematicBreak'];
42. 
43.     /**
44.      * Node types that can contain "block" nodes as direct children. We check
45.      */
46.     const canContainBlocks = ['root', 'blockquote', 'listItem', 'tableCell'];
47. 
48.     let invalidNest;
49. 
50.     visitParents(tree, (node, parents) => {
51.       const parentType = !isEmpty(parents) && last(parents).type;
52.       const isInvalidNest = blocks.includes(node.type) && !canContainBlocks.includes(parentType);
53. 
54.       if (isInvalidNest) {
55.         invalidNest = concat(parents, node);
56.         return false;
57.       }
58.     });
59. 
60.     return invalidNest;
61.   }
62. 
63.   function splitTreeAtNest(tree, nest) {
64.     const grandparent = nth(nest, -3) || tree;
65.     const parent = nth(nest, -2);
66.     const node = last(nest);
67. 
68.     const splitIndex = grandparent.children.indexOf(parent);
69.     const splitChildren = grandparent.children;
70.     const splitChildIndex = parent.children.indexOf(node);
71. 
72.     const childrenBefore = parent.children.slice(0, splitChildIndex);
73.     const childrenAfter = parent.children.slice(splitChildIndex + 1);
74.     const nodeBefore = !isEmpty(childrenBefore) && { ...parent, children: childrenBefore };
75.     const nodeAfter = !isEmpty(childrenAfter) && { ...parent, children: childrenAfter };
76. 
77.     const childrenToInsert = [nodeBefore, node, nodeAfter].filter(val => !isEmpty(val));
78.     const beforeChildren = splitChildren.slice(0, splitIndex);
79.     const afterChildren = splitChildren.slice(splitIndex + 1);
80.     const newChildren = concat(beforeChildren, childrenToInsert, afterChildren);
81.     grandparent.children = newChildren;
82.   }
83. }
84.

